package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLineHasOptionTest {

    @Test
    void testHasOptionNotPresent() throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);

        List<String> args = new ArrayList<>();
        List<Option> options = new ArrayList<>();
        AtomicBoolean invoked = new AtomicBoolean(false);
        Consumer<Option> handler = o -> invoked.set(true);

        CommandLine cmd = ctor.newInstance(args, options, handler);

        Option opt = new Option("a", "description");
        // option not present in list -> should return false and not invoke handler
        assertFalse(cmd.hasOption(opt));
        assertFalse(invoked.get());
    }

    @Test
    void testHasOptionPresentNotDeprecated() throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);

        List<String> args = new ArrayList<>();
        List<Option> options = new ArrayList<>();
        Option opt = new Option("b", "description");
        options.add(opt);

        AtomicBoolean invoked = new AtomicBoolean(false);
        Consumer<Option> handler = o -> invoked.set(true);

        CommandLine cmd = ctor.newInstance(args, options, handler);

        // option present but not deprecated -> should return true and not invoke handler
        assertTrue(cmd.hasOption(opt));
        assertFalse(invoked.get());
    }

    @Test
    void testHasOptionPresentDeprecatedInvokesHandler() throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);

        List<String> args = new ArrayList<>();
        List<Option> options = new ArrayList<>();
        DeprecatedOption depr = new DeprecatedOption("c");
        options.add(depr);

        AtomicBoolean invoked = new AtomicBoolean(false);
        Consumer<Option> handler = o -> {
            // ensure the handler receives the same option instance
            invoked.set(o == depr);
        };

        CommandLine cmd = ctor.newInstance(args, options, handler);

        // option present and overridden to be deprecated -> should return true and invoke handler
        assertTrue(cmd.hasOption(depr));
        assertTrue(invoked.get());
    }

    // helper subclass overriding isDeprecated to simulate a deprecated Option
    static class DeprecatedOption extends Option {
        DeprecatedOption(String opt) {
            super(opt, "deprecated");
        }

        @Override
        public boolean isDeprecated() {
            return true;
        }
    }
}

